declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$minutes=max(5,min(10080,(int)setting('abandoned_cart_minutes','30')));db()->exec("UPDATE abandoned_carts SET status='expired' WHERE status='active' AND last_activity_at<DATE_SUB(NOW(),INTERVAL 30 DAY)");$stmt=db()->query("SELECT a.*,c.full_name,o.order_number FROM abandoned_carts a LEFT JOIN customers c ON c.id=a.customer_id LEFT JOIN orders o ON o.id=a.recovered_order_id WHERE a.status<>'active' OR a.last_activity_at<DATE_SUB(NOW(),INTERVAL {$minutes} MINUTE) ORDER BY a.last_activity_at DESC LIMIT 500");$rows=$stmt->fetchAll();$adminPage='abandoned';$adminTitle='سبدهای رهاشده';require __DIR__.'/partials/header.php';?>
<div class="admin-title"><h1>سبدهای رهاشده</h1><span>رهاشده پس از <?=fa_number($minutes)?> دقیقه</span></div><div class="card table-wrap"><table><thead><tr><th>آخرین فعالیت</th><th>مشتری</th><th>اقلام</th><th>مبلغ</th><th>کد تخفیف</th><th>وضعیت</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e(jalali_format($row['last_activity_at']))?></td><td><?=e($row['full_name']?:($row['phone']?:'مهمان'))?></td><td><?=fa_number($row['items_count'])?></td><td><?=fa_number(format_price($row['subtotal']))?> تومان</td><td><?=e($row['coupon_code']?:'—')?></td><td><?=e(['active'=>'رهاشده','recovered'=>'تبدیل به سفارش','expired'=>'منقضی'][$row['status']]??$row['status'])?><?php if($row['order_number']):?><br><?=e($row['order_number'])?><?php endif?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6">سبد رهاشده‌ای وجود ندارد.</td></tr><?php endif?></tbody></table></div>
